create table if not exists public.submissions(id bigint generated by default as identity primary key,code text not null check(char_length(code) between 1 and 2000),created_at timestamptz not null default now());
alter table public.submissions enable row level security;
create policy "Public can read submissions" on public.submissions for select to anon,authenticated using(true);
create policy "Anyone can submit codes" on public.submissions for insert to anon,authenticated with check(true);
create table if not exists public.portal_admins(user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz not null default now());
alter table public.portal_admins enable row level security;
create policy "Admins can read own admin record" on public.portal_admins for select to authenticated using(auth.uid()=user_id);
create policy "Admins can update submissions" on public.submissions for update to authenticated using(exists(select 1 from public.portal_admins a where a.user_id=auth.uid())) with check(exists(select 1 from public.portal_admins a where a.user_id=auth.uid()));
create policy "Admins can delete submissions" on public.submissions for delete to authenticated using(exists(select 1 from public.portal_admins a where a.user_id=auth.uid()));